def read_ints():
    return list(map(int, input().split()))

def read_matrix(n, m, k):
    return [input() for _ in range(n)]

def is_critical(n, m, k, layers, x, y, z):
    # Check if turning off (x, y, z) will disrupt control
    for dx in range(1, n):
        if x + dx < n and layers[x + dx][y][z] == '1':
            for dy in range(1, m):
